from __future__ import absolute_import

from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.oam.coam_cbts_cu.base import BaseClass

logger = BackgroundLogger.Instance()


class VNFOperations(BaseClass):
    """
    DU Operations
    """

    def __init__(self):
        super(VNFOperations, self).__init__()

    def get_cu_vnf(self, **kwargs):
        timeout = kwargs.get("timeout", 10)
        connection = kwargs.get("alias", "default")

        return self.factory.cu_oam.get_cu_vnf(timeout=timeout, connection=connection)

    def activate_cu_vnf(self, **kwargs):
        forceful_activation = kwargs.get("forceful_activation", False)
        timeout = kwargs.get("timeout", 10)
        connection = kwargs.get("alias", "default")

        if forceful_activation:
            return self.factory.cu_oam.forcefully_activate_cu_vnf(timeout=timeout, connection=connection)
        else:
            return self.factory.cu_oam.activate_cu_vnf(timeout=timeout, connection=connection)

    def get_vnfcs_states(self, **kwargs):
        use_m2m = kwargs.get("use_m2m", True)
        connection = kwargs.get("alias", "default")
        pod_name = kwargs.get("pod_name", None)
        status = self.factory.cu_oam.get_vnfcs_states(use_m2m=use_m2m, connection=connection)

        if pod_name:
            status_dict = {}
            if isinstance(pod_name, str):
                pod_name = [pod_name]
                count = 1
            else:
                # pod_name is a list
                count = len(pod_name)
            for i in status:
                if i["name"] in pod_name:
                    print("pod name:", i["name"])
                    name = i.pop("name")
                    status_dict[name] = i
                    count = count - 1
                if count == 0:
                    break
            status = status_dict

        return status

    def deactivate_cu_vnf(self, **kwargs):
        timeout = kwargs.get("timeout", 10)
        connection = kwargs.get("alias", "default")

        return self.factory.cu_oam.deactivate_cu_vnf(timeout=timeout, connection=connection)

    def get_deactivate_cu_vnf_status(self, **kwargs):
        timeout = kwargs.get("timeout", 10)
        connection = kwargs.get("alias", "default")

        return self.factory.cu_oam.get_deactivate_cu_vnf_status(timeout=timeout, connection=connection)

    def get_activate_cu_vnf_status(self, **kwargs):
        operation_id = kwargs["operation_id"]
        forceful = kwargs.get("forceful", False)
        timeout = kwargs.get("timeout", 10)
        connection = kwargs.get("alias", "default")

        if not forceful:
            return self.factory.cu_oam.get_activate_cu_vnf_status(operation_id=operation_id, timeout=timeout,
                                                                    connection=connection)
        else:
            return self.factory.cu_oam.get_forcefully_activate_cu_vnf_status(operation_id=operation_id,
                                                                               timeout=timeout, connection=connection)
